c3_summaries &lt;- list()
if (!is.null(post_c3_os))    c3_summaries &lt;- c(c3_summaries, list(or_summary(post_c3_os,    "b_ptcy_binary", "OS",      "C3", "M1")))
if (!is.null(post_c3_nrm))   c3_summaries &lt;- c(c3_summaries, list(or_summary(post_c3_nrm,   "b_ptcy_binary", "NRM",     "C3", "M1")))
if (!is.null(post_c3_rrm))   c3_summaries &lt;- c(c3_summaries, list(or_summary(post_c3_rrm,   "b_ptcy_binary", "RRM",     "C3", "M1")))
if (!is.null(post_c3_agvhd)) c3_summaries &lt;- c(c3_summaries, list(or_summary(post_c3_agvhd, "b_ptcy_binary", "aGVHD",   "C3", "M1")))
if (!is.null(post_c3_cgvhd)) c3_summaries &lt;- c(c3_summaries, list(or_summary(post_c3_cgvhd, "b_ptcy_binary", "cGVHD",   "C3", "M1")))

if (length(c3_summaries) &gt; 0) {
  c3_pd &lt;- do.call(rbind, c3_summaries) |&gt;
    as_tibble() |&gt;
    mutate(
      outcome = factor(outcome, levels = rev(c("OS", "NRM", "RRM", "aGVHD", "cGVHD"))),
      label = sprintf("%.2f [%.2f, %.2f]", or, lo, hi)
    )

  ggplot(c3_pd, aes(x = or, y = outcome)) +
    geom_vline(xintercept = 1, linetype = "dashed", colour = jama_grey) +
    geom_pointrange(aes(xmin = lo, xmax = hi), colour = jama_navy, size = 0.5, linewidth = 0.5) +
    geom_text(aes(x = hi, label = label), hjust = -0.1, size = 3, colour = jama_black) +
    scale_x_log10(breaks = c(0.3, 0.5, 0.7, 1, 1.5, 2)) +
    coord_cartesian(xlim = c(0.25, 2.5)) +
    labs(x = "Odds Ratio (log scale)", y = NULL,
         title = "Comparison 3: Within-PTCy Regimen Variants",
         subtitle = "All outcomes null — choice of backbone IS does not significantly alter PTCy benefit") +
    theme_jama()
}








Figure 3: Summary forest plot for all Comparison 3 outcomes. All CrIs cross the null, indicating no significant differences between PTCy regimen variants.











TipClinical Interpretation



The null findings across all C3 outcomes suggest that the PTCy component dominates the regimen effect, regardless of whether the backbone immunosuppression uses tacrolimus/MMF, sirolimus, or other combinations. This supports the concept that PTCy’s alloreactive T-cell depletion is the primary driver of GVHD prophylaxis efficacy, with the choice of co-administered agents playing a secondary role.
The only suggestive signal is for chronic GVHD (OR 0.67, P(OR &lt; 1) = 93%), which may warrant further investigation in larger datasets.

ROB Summary


Show code
if (!is.null(rob)) {
  domain_labels &lt;- c(
    d1 = "Confounding", d2 = "Selection", d3 = "Classification",
    d4 = "Deviations", d5 = "Missing data", d6 = "Measurement", d7 = "Reporting"
  )

  rob_long &lt;- rob |&gt;
    select(study_id, d1:d7) |&gt;
    pivot_longer(-study_id, names_to = "domain", values_to = "judgment") |&gt;
    mutate(
      domain = domain_labels[domain],
      judgment = factor(judgment,
                        levels = c("Low", "Moderate", "Serious", "Critical", "NR"),
                        labels = c("Low", "Moderate", "Serious", "Critical", "Not reported"))
    ) |&gt;
    filter(!is.na(judgment))

  rob_counts &lt;- rob_long |&gt;
    count(domain, judgment) |&gt;
    group_by(domain) |&gt;
    mutate(pct = n / sum(n) * 100)

  ggplot(rob_counts, aes(x = pct, y = reorder(domain, pct), fill = judgment)) +
    geom_col(width = 0.7) +
    scale_fill_manual(values = c(
      "Low" = "#a3c1d4",
      "Moderate" = jama_light_grey,
      "Serious" = jama_steel,
      "Critical" = jama_dark,
      "Not reported" = "white"
    ), drop = FALSE) +
    labs(x = "Percentage of studies", y = NULL, fill = "Judgment",
         title = "Risk-of-Bias Summary by Domain") +
    theme_jama() +
    theme(legend.position = "bottom")
} else {
  cat("ROB data not found in extraction directory. This page will be populated when rob.csv is available.")
}








Figure 1: Risk-of-bias summary across all included studies. Most studies carry moderate or serious risk of bias, primarily in the confounding and selection domains — consistent with the observational study design.
